  function apply(lang) {
    const t = translations[lang] || translations.fa;
    const rtl = ["fa","ku","ar"].includes(lang);
    const guideHero = serviceGuideHeroTranslations[lang] || serviceGuideHeroTranslations.fa;
    document.querySelectorAll("[data-guide-hero]").forEach(node=>{const key=node.getAttribute("data-guide-hero");if(guideHero[key])node.textContent=guideHero[key][0];});
    document.querySelectorAll("[data-guide-lead]").forEach(node=>{const key=node.getAttribute("data-guide-lead");if(guideHero[key])node.textContent=guideHero[key][1];});
    document.documentElement.lang = lang;
    document.documentElement.dir = rtl ? "rtl" : "ltr";
    document.querySelectorAll("[data-i18n]").forEach(node=>{
      const key=node.getAttribute("data-i18n");
      if(t[key]) node.textContent=t[key];
    });
    document.querySelectorAll("[data-i18n-placeholder]").forEach(node=>{
      const key=node.getAttribute("data-i18n-placeholder");
      if(t[key]) node.setAttribute("placeholder",t[key]);
    });
    document.querySelectorAll("[data-i18n-show-non-fa]").forEach(node=>{
      node.hidden = lang === "fa";
    });
    Object.entries(keys).forEach(([selector,key]) => {
      const node = document.querySelector(selector);
      if (node && t[key]) node.textContent = t[key];
    });
    const labels = document.querySelectorAll("#searchForm label");
    if (labels[0]) labels[0].childNodes[0].textContent = t.languageFilter + " ";
    if (labels[1]) labels[1].childNodes[0].textContent = t.specialtyFilter + " ";
    const button = document.querySelector("#searchForm button");
    if (button) button.textContent = t.search;
    document.querySelectorAll(".service-grid .service").forEach((node,i) => {
      const n=i+1; const h=node.querySelector("h3"), p=node.querySelector("p"), link=node.querySelector("a");
      if(h && t["s"+n]) h.textContent=t["s"+n];
      if(p && t["s"+n+"p"]) p.textContent=t["s"+n+"p"];
      if(link && t["serviceGuide"+n]) link.textContent=t["serviceGuide"+n];
    });
    document.querySelectorAll("#how .steps>div").forEach((node,i) => {
      const n=i+1, h=node.querySelector("h3"), p=node.querySelector("p");
      if(h && t["step"+n]) h.textContent=t["step"+n];
      if(p && t["step"+n+"p"]) p.textContent=t["step"+n+"p"];
    });
    const langSelect=document.getElementById("siteLanguage");
    if(langSelect) langSelect.value=lang;
    try { localStorage.setItem("yad-language",lang); } catch (_) {}
    document.dispatchEvent(new CustomEvent("yad:languagechange",{detail:{language:lang}}));
  }
  if(!document.getElementById("siteLanguage")){
    const host=document.querySelector(".navrow")||document.querySelector(".portal-wrap")||document.body;
    const label=document.createElement("label");label.className="market-switch language-switch universal-language";label.setAttribute("aria-label","Language");
    label.textContent="🌐 ";
    const picker=document.createElement("select");picker.id="siteLanguage";picker.setAttribute("aria-label","Language");
    [["fa","فارسی"],["ku","کوردی"],["en","English"],["tr","Türkçe"],["ar","العربية"],["es","Español"],["de","Deutsch"],["fr","Français"]].forEach(([value,name])=>{const o=document.createElement("option");o.value=value;o.textContent=name;picker.append(o);});
    label.append(picker);
    if(host===document.body){label.classList.add("universal-language-floating");host.prepend(label);}else host.prepend(label);
  }
  const select=document.getElementById("siteLanguage");
  if(select) {
    let saved="fa";
    try { const candidate=localStorage.getItem("yad-language"); if(translations[candidate]) saved=candidate; } catch (_) {}
    select.value=saved;
    apply(saved);
    select.addEventListener("change",()=>apply(select.value));
  }

  if(!document.querySelector(".yad-assessment-float")){
    const labels={fa:"راهنمای اولیه انتخاب درمانگر",ku:"ڕێنمایی سەرەتایی بۆ هەڵبژاردنی چارەسەرکار",en:"Initial guide to choosing a therapist",tr:"Terapist seçimi için başlangıç rehberi",ar:"دليل أولي لاختيار المعالج",es:"Guía inicial para elegir terapeuta",de:"Erste Orientierung zur Therapeutenauswahl",fr:"Guide initial pour choisir un thérapeute"};
    const link=document.createElement("a");link.className="yad-assessment-float";link.href=(location.pathname.includes("/articles/")?"../":"")+"initial-guidance.html";link.textContent=labels[document.documentElement.lang]||labels.fa;link.setAttribute("aria-label",link.textContent);document.body.appendChild(link);
  }
